import importlib.util
from pathlib import Path
import unittest


ROOT = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location("figure_text_policy", ROOT / "scripts/figure_text_policy.py")
POLICY = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(POLICY)


class FigureTextPolicyTests(unittest.TestCase):
    def test_explicit_production_audit_and_disclaimer_phrases_rejected(self):
        prohibited = [
            "AI note: visualization only", "AI insight", "ChatGPT remarks",
            "Generated by ChatGPT", "Created by OpenAI", "Prepared by artificial intelligence",
            "Generated figure", "AI-generated plot", "Generated by an AI",
            "CP2 PASS", "CP4: FAIL", "CP3_NOT_VERIFIED", "CP2 PENDING", "NOT_VERIFIED",
            "Pairing: not verified", "For illustration only", "Descriptive only",
            "For demonstration only", "ＡＩ　ｎｏｔｅ: one panel", "Generated\nby\tChatGPT",
            "AI\u200b note", "Generated by Chat\ufeffGPT",
            "AI备注", "AI 注释", "人工智能的说明", "自动生成图", "AI生成的科研图",
            "仅作演示", "仅用于演示", "只供示意", "配对未核", "参考配对尚未验证", "科研结论未验证",
        ]
        for text in prohibited:
            with self.subTest(text=text):
                self.assertIsNotNone(POLICY.forbidden_figure_text_reason(text))

    def test_scientific_annotations_and_identifiers_are_not_broadly_banned(self):
        legitimate = [
            "AI", "AI prediction score", "AI_NOTE_01", "AI_insight_gene", "AI基因表达量",
            "AI-generated risk score", "AI-generated", "AI-assisted", "AI-generated image",
            "AI-generated images", "AI生成图像组", "自动生成", "Artificial intelligence model performance",
            "Germline mutation frequency", "Drug-only control", "WT only", "only",
            "Simulated score (a.u.)", "Synthetic value", "Dose (mg)", "Count",
            "n = 30", "P = 0.02", "q < 0.05", "r = 0.72", "R² = 0.51", "ns",
            "50 μm", "0", "1.5", "NOT_VERIFIED_GENE", "CP2_PASS_01", "Pairing factor",
        ]
        for text in legitimate:
            with self.subTest(text=text):
                self.assertIsNone(POLICY.forbidden_figure_text_reason(text))

    def test_phrase_check_returns_field_and_location(self):
        errors = POLICY.validate_figure_text(["Dose (mg)", "AI note"], "rendered_text")
        self.assertEqual(len(errors), 1)
        self.assertIn("rendered_text[1]", errors[0])
        self.assertIn("keep it outside the figure", errors[0])

    def test_malformed_non_strings_remain_a_schema_concern(self):
        self.assertEqual(POLICY.validate_figure_text(["Dose (mg)", None, 5]), [])


if __name__ == "__main__":
    unittest.main()
